extractor "snapshot-http" version="2026-07-15" language-version="2026-07-15" {
  source "html" { fetch mode="http" url="https://example.invalid/" }
  field "title" type="string" required=#true { select "h1"; value "text" }
}

extractor "snapshot-portable" version="2026-07-15" language-version="2026-07-15" {
  source "html" { fetch mode="browser" url="https://example.invalid/" }
  field "title" type="string" required=#true { select "h1"; value "text" }
  collection "items" min-items=1 {
    select "ul > li"
    field "name" type="string" required=#true { select "span"; value "text" }
  }
}

extractor "snapshot-runtime-contracts" version="2026-07-15" language-version="2026-07-15" {
  source "html" { fetch mode="browser" url="https://example.invalid/" }
  transform "decorate" input="string" output="string" { external symbol="decorate" }
  field "decorated" type="string" required=#true { select "#name"; value "text"; apply "decorate" }
  field "warned" type="string?" required=#false {
    select "#bad"; value "text"; apply "assert-matches" pattern="^ok$"; on-error "warn"
  }
}

extractor "snapshot-workflow" version="2026-07-15" language-version="2026-07-15" {
  source "html" {
    fetch mode="browser" url="https://example.invalid/"
    workflow { click "button.load" }
  }
  field "title" type="string" required=#true { select "h1"; value "text" }
}

extractor "snapshot-javascript" version="2026-07-15" language-version="2026-07-15" {
  source "html" { fetch mode="browser" url="https://example.invalid/" }
  field "computed" type="string" required=#true {
    evaluate-js "() => document.title" scope="document" returns="string"
  }
}
